SELECT agent_id AS agentId, app_name AS appName, agent_name AS agentName,
       agent_desc AS agentDesc, enabled
FROM ai_agent_app_config WHERE agent_id = #{agentId}

SELECT api_config_json AS apiConfig, chat_model_json AS chatModelConfig,
       runner_config_json AS runnerConfig
FROM ai_agent_model_config WHERE agent_id=#{agentId}
